import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class SplitITupVariant5 {
    public static void main(String[] args) {
        List<Integer> leftBracketPositions = new ArrayList<>();
        List<Integer> rightBracketPositions = new ArrayList<>();
        Scanner sc = new Scanner(System.in);
        int totalPairs = sc.nextInt();
        String sequence = sc.next();

        for (int i = 0; i < totalPairs; i++) {
            if (sequence.charAt(i) == '(') {
                leftBracketPositions.add(i);
            } else if (sequence.charAt(i) == ')') {
                rightBracketPositions.add(i);
            }
        }

        int totalWords = 0;
        for (String segment : getSegments(sequence, leftBracketPositions, rightBracketPositions)) {
            String[] parts = segment.split("_");
            for (String part : parts) {
                if (!part.isEmpty()) {
                    totalWords++;
                }
            }
        }

        int maxWordLength = 0;
        leftBracketPositions.add(sequence.length());
        rightBracketPositions.add(0, 0);
        int startIdx = sequence.charAt(0) == '(' ? 1 : 0;

        for (int i = startIdx; i < rightBracketPositions.size(); i++) {
            String segment;
            if (sequence.charAt(rightBracketPositions.get(i)) == ')') {
                segment = sequence.substring(rightBracketPositions.get(i) + 1, leftBracketPositions.get(i));
            } else {
                segment = sequence.substring(rightBracketPositions.get(i), leftBracketPositions.get(i));
            }
            String[] parts = segment.split("_");
            for (String part : parts) {
                if (part.length() > maxWordLength && !part.contains("(") && !part.contains(")")) {
                    maxWordLength = part.length();
                }
            }
        }
        System.out.println(maxWordLength + " " + totalWords);
    }

    private static List<String> getSegments(String s, List<Integer> starts, List<Integer> ends) {
        List<String> segments = new ArrayList<>();
        for (int i = 0; i < starts.size(); i++) {
            segments.add(s.substring(starts.get(i) + 1, ends.get(i)));
        }
        return segments;
    }
}
